import React, { useEffect, useState } from "react";
import { AlertTriangle, BarChart3, FileUp, ShieldCheck, Sparkles } from "lucide-react";
import MarkdownMessage from "./MarkdownMessage";
import { readSection, updateSection } from "../ui/navigation";
import { confirmLifeOs, notifyLifeOs } from "../ui/feedback";

const money = new Intl.NumberFormat("en-ZA", { style: "currency", currency: "ZAR" });
const LIFEOS_TIMEZONE = "Africa/Johannesburg";
const lifeOsDateTime = new Intl.DateTimeFormat("en-ZA", { timeZone: LIFEOS_TIMEZONE, day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false, timeZoneName: "short" });
const lifeOsToday = () => new Intl.DateTimeFormat("en-CA", { timeZone: LIFEOS_TIMEZONE, year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date());

type InsightView="spending"|"accounts"|"upload"|"balances"|"screenshots"|"review"|"tools";
export default function FinanceInsightsPanel({ accounts, cards, transactions, onSaved, initialView }: { accounts: any[]; cards: any[]; transactions: any[]; onSaved: () => Promise<void>;initialView?:InsightView }) {
  const [data, setData] = useState<any>();
  const [reserve, setReserve] = useState("");
  const [csv, setCsv] = useState("");
  const [pdfBase64, setPdfBase64] = useState("");
  const [imageBase64, setImageBase64] = useState("");
  const [balanceImageBase64, setBalanceImageBase64] = useState("");
  const [balanceImageName, setBalanceImageName] = useState("");
  const [balanceDocumentId, setBalanceDocumentId] = useState("");
  const [balanceProposals, setBalanceProposals] = useState<any[]>([]);
  const [balanceAnalyzing, setBalanceAnalyzing] = useState(false);
  const [fileName, setFileName] = useState("");
  const [accountId, setAccountId] = useState(()=>new URLSearchParams(window.location.search).get("account")||"");
  const [positiveCreditMeansSpending, setPositiveCreditMeansSpending] = useState(true);
  const [newDebit, setNewDebit] = useState({ name: "", institution: "", balance: "" });
  const [analyzing, setAnalyzing] = useState(false);
  const [approvalOpen, setApprovalOpen] = useState(false);
  const [approvalSearch, setApprovalSearch] = useState(()=>new URLSearchParams(window.location.search).get("filter")||"");
  const [approvalLimit, setApprovalLimit] = useState(25);
  const [analysisAccount, setAnalysisAccount] = useState("all");
  const insightViews=["spending","accounts","upload","balances","screenshots","review","tools"];
  const [insightView, setInsightView] = useState<InsightView>(()=>(initialView||readSection("financeDetail",insightViews,"spending")) as InsightView);
  const [selectedScreenshotId, setSelectedScreenshotId] = useState(()=>new URLSearchParams(window.location.search).get("document")||"");
  const [screenshotDrafts, setScreenshotDrafts] = useState<Record<string, any>>({});
  const [screenshotSaving, setScreenshotSaving] = useState("");
  const [showConfirmedScreenshotRows, setShowConfirmedScreenshotRows] = useState(false);
  const [balanceConfirm, setBalanceConfirm] = useState({ balance: "", balanceAsOf: lifeOsToday() });
  const [briefingLoading, setBriefingLoading] = useState(false);
  const [reviewItem, setReviewItem] = useState<any>(null);
  const [customCategory, setCustomCategory] = useState("");
  useEffect(()=>{if(initialView)setInsightView(initialView)},[initialView]);
  useEffect(()=>{updateSection("financeDetail",insightView)},[insightView]);
  useEffect(()=>{const url=new URL(window.location.href);if(accountId)url.searchParams.set("account",accountId);else url.searchParams.delete("account");if(selectedScreenshotId)url.searchParams.set("document",selectedScreenshotId);else url.searchParams.delete("document");if(approvalSearch)url.searchParams.set("filter",approvalSearch);else url.searchParams.delete("filter");window.history.replaceState({},"",url)},[accountId,selectedScreenshotId,approvalSearch]);
  const [rememberCategory, setRememberCategory] = useState(true);
  const [categorySaving, setCategorySaving] = useState(false);
  const [statement, setStatement] = useState({ liabilityId: "", statementDate: lifeOsToday(), dueDate: "", statementBalance: "", minimumDue: "" });
  const refresh = async () => { const response = await fetch(`/api/personal/finance/insights?fresh=${Date.now()}`, { cache: "no-store" }); if (response.ok) { const next = await response.json(); setData(next); setReserve(String(next.emergencyFund.target || "")); } };
  useEffect(() => { refresh(); }, []);
  const financeRefreshKey = [...accounts, ...cards].map((item:any)=>`${item.id}:${item.balance}:${item.balanceAsOf||item.balanceUpdatedAt||item.updatedAt||""}:${item.availableCredit??""}`).join("|") + `|transactions:${transactions.map((item:any)=>`${item.id}:${item.status}:${item.updatedAt||item.reconciledAt||""}`).join("|")}`;
  useEffect(() => { void refresh(); }, [financeRefreshKey]);
  useEffect(() => { if (!data || balanceProposals.length) return; const document=(data.balanceScreenshotDocuments||[]).find((item:any)=>item.status==="awaiting-confirmation"); if(!document)return; const proposals=(data.balanceUpdateProposals||[]).filter((item:any)=>item.documentId===document.id&&item.status==="pending"); if(proposals.length){setBalanceDocumentId(document.id);setBalanceProposals(proposals);} }, [data]);
  const saveReserve = async () => { await fetch("/api/personal/onboarding", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ emergencyFundTarget: Number(reserve || 0) }) }); await refresh(); };
  const importCsv = async (event: React.FormEvent) => { event.preventDefault(); setAnalyzing(true); try { const wasScreenshot = Boolean(imageBase64); const [accountKind, selectedId] = accountId.split(":"); const response = await fetch("/api/personal/finance/bank-statements/import", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ accountKind, accountId: selectedId, positiveCreditMeansSpending, csv, pdfBase64, imageBase64, fileName }) }); const result = await response.json(); if (!response.ok) return alert(result.error); const balanceMessage = result.balanceUpdate ? ` ${result.balanceUpdate.accountName} balance updated from ${money.format(result.balanceUpdate.previousBalance)} to ${money.format(result.balanceUpdate.balance)} as of ${result.balanceUpdate.asOfDate}.` : wasScreenshot ? " No balance was visible with enough confidence; confirm it in Screenshot review." : " No newer high-confidence balance was applied."; alert(`${result.imported} imported; ${result.duplicates} duplicates skipped.${balanceMessage} ${result.analysis ? `${result.analysis.provider} analysis saved to LifeOS memory.` : ""}`); setCsv(""); setPdfBase64(""); setImageBase64(""); setFileName(""); if (wasScreenshot) { setSelectedScreenshotId(result.statementDocumentId || ""); setInsightView("screenshots"); } await Promise.all([onSaved(), refresh()]); } finally { setAnalyzing(false); } };
  const loadStatementFile = async (event: React.ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; const lower = file.name.toLowerCase(), image = file.type.startsWith("image/") || /\.(png|jpe?g|heic|heif)$/.test(lower); if (!lower.endsWith(".csv") && !lower.endsWith(".pdf") && !image) { event.target.value = ""; return alert("Please select a CSV, PDF, PNG, JPG, or HEIC file."); } const limit = image ? 6 : 5; if (file.size > limit * 1024 * 1024) { event.target.value = ""; return alert(`Files must be ${limit} MB or smaller.`); } setFileName(file.name); if (lower.endsWith(".pdf") || image) { setCsv(""); const encoded = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result || "")); reader.onerror = () => reject(new Error("Could not read file")); reader.readAsDataURL(file); }); setPdfBase64(image ? "" : encoded); setImageBase64(image ? encoded : ""); } else { setPdfBase64(""); setImageBase64(""); setCsv(await file.text()); } };
  const loadBalanceScreenshot = async (event: React.ChangeEvent<HTMLInputElement>) => { const file=event.target.files?.[0]; if(!file)return; if(file.size>6*1024*1024)return alert("Balance screenshots must be 6 MB or smaller."); const encoded=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||""));reader.onerror=()=>reject(new Error("Could not read screenshot"));reader.readAsDataURL(file);});setBalanceImageBase64(encoded);setBalanceImageName(file.name);setBalanceDocumentId("");setBalanceProposals([]); };
  const analyzeBalances = async () => { if(!balanceImageBase64)return;setBalanceAnalyzing(true);try{const response=await fetch("/api/personal/finance/balance-screenshots/analyze",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({imageBase64:balanceImageBase64,fileName:balanceImageName})});const result=await response.json();if(!response.ok)return alert(result.error);setBalanceDocumentId(result.document.id);setBalanceProposals(result.proposals);await refresh();}finally{setBalanceAnalyzing(false);} };
  const confirmBalances = async () => { if(!balanceDocumentId||!balanceProposals.length)return;setBalanceAnalyzing(true);try{const response=await fetch(`/api/personal/finance/balance-screenshots/${balanceDocumentId}/confirm`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({proposals:balanceProposals})});const result=await response.json();if(!response.ok)return alert(result.error);alert(`${result.applied.length} account balance${result.applied.length===1?"":"s"} updated across LifeOS.`);setBalanceImageBase64("");setBalanceImageName("");setBalanceDocumentId("");setBalanceProposals([]);await Promise.all([onSaved(),refresh()]);}finally{setBalanceAnalyzing(false);} };
  const removeBalanceScreenshot = async (document:any) => { const confirmed=(data.balanceUpdateProposals||[]).filter((item:any)=>item.documentId===document.id&&item.status==="confirmed").length; const warning=confirmed?"Balances already confirmed from it remain unchanged.":"All pending balance proposals will also be removed."; if(!await confirmLifeOs(`Remove ${document.originalFileName}?`,warning))return; const response=await fetch(`/api/personal/finance/balance-screenshots/${document.id}`,{method:"DELETE"});const result=await response.json();if(!response.ok)return notifyLifeOs(result.error,"danger");if(balanceDocumentId===document.id){setBalanceDocumentId("");setBalanceProposals([]);}await refresh();notifyLifeOs(result.message,"success"); };
  const reconcile = (item: any) => { setReviewItem(item); setCustomCategory(""); setRememberCategory(item.suggestedCategory !== "Internal transfer"); };
  const applyCategory = async (category: string) => { if (!reviewItem || !category.trim()) return; setCategorySaving(true); try { const response = await fetch(`/api/personal/finance/bank-transactions/${reviewItem.id}/reconcile`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ category: category.trim(), learnMerchant: category !== "Internal transfer" && rememberCategory }) }); if (!response.ok) return alert((await response.json()).error); setReviewItem(null); await Promise.all([onSaved(), refresh()]); } finally { setCategorySaving(false); } };
  const bulkReconcile = async (source: "cross-account-match" | "learned-merchant-rule", count: number) => { if (!count || !await confirmLifeOs(`Approve ${count} transactions?`,`Approve all ${source === "cross-account-match" ? "matched transfers" : "learned merchant matches"}, add them to the ledger, and retain an audit record.`)) return; const response = await fetch("/api/personal/finance/bank-transactions/bulk-reconcile", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ source }) }); const result = await response.json(); if (!response.ok) return notifyLifeOs(result.error,"danger"); notifyLifeOs(`${result.reconciled} transactions approved.`,"success"); await Promise.all([onSaved(), refresh()]); };
  const createBriefing = async () => { setBriefingLoading(true); try { const response = await fetch("/api/personal/finance/ai-briefing", { method: "POST" }); const result = await response.json(); if (!response.ok) return alert(result.error); await refresh(); } finally { setBriefingLoading(false); } };
  const saveStatement = async (event: React.FormEvent) => { event.preventDefault(); const response = await fetch("/api/personal/finance/card-statements", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ...statement, statementBalance: Number(statement.statementBalance), minimumDue: Number(statement.minimumDue) }) }); if (!response.ok) return alert((await response.json()).error); await onSaved(); await refresh(); };
  const addDebitAccount = async (event: React.FormEvent) => { event.preventDefault(); const response = await fetch("/api/personal/finance/bank-accounts", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ name: newDebit.name, institution: newDebit.institution, accountType: "Debit account", balance: Number(newDebit.balance || 0) }) }); const result = await response.json(); if (!response.ok) return alert(result.error); setAccountId(`debit:${result.id}`); setNewDebit({ name: "", institution: "", balance: "" }); await onSaved(); };
  const saveScreenshotRow = async (item: any) => { const draft = screenshotDrafts[item.id] || item; setScreenshotSaving(item.id); try { const response = await fetch(`/api/personal/finance/bank-transactions/${item.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ date: draft.date, description: draft.description, amount: Number(draft.amount), category: draft.category || draft.suggestedCategory || "Other" }) }); const result = await response.json(); if (!response.ok) return alert(result.error); setScreenshotDrafts(current=>{const next={...current};delete next[item.id];return next;}); await Promise.all([onSaved(),refresh()]); } finally { setScreenshotSaving(""); } };
  const confirmScreenshotBalance = async (event: React.FormEvent) => { event.preventDefault(); if (!selectedScreenshotId) return; setScreenshotSaving("balance"); try { const response = await fetch(`/api/personal/finance/bank-statement-documents/${selectedScreenshotId}/confirm-balance`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ balance: Number(balanceConfirm.balance), balanceAsOf: balanceConfirm.balanceAsOf }) }); const result = await response.json(); if (!response.ok) return alert(result.error); alert(`${result.account.name} main balance updated from ${money.format(result.previousBalance)} to ${money.format(result.account.balance)}.`); setBalanceConfirm(current=>({...current,balance:""})); await Promise.all([onSaved(),refresh()]); } finally { setScreenshotSaving(""); } };
  if (!data) return <div className="bg-white border rounded-2xl p-5">Calculating finance insights…</div>;
  const maxPaid = Math.max(1, ...data.history.map((x: any) => x.paid));
  const pendingTransactions = transactions.filter((item) => item.status === "unreconciled");
  const filteredPending = pendingTransactions.filter((item) => `${item.date} ${item.description} ${item.suggestedCategory || ""} ${item.amount}`.toLowerCase().includes(approvalSearch.toLowerCase()));
  const transferCandidates = pendingTransactions.filter((item) => item.classificationSource === "cross-account-match").length;
  const learnedClassifications = pendingTransactions.filter((item) => item.classificationSource === "learned-merchant-rule").length;
  const analysisAccounts = data.transactionIntelligence?.accountCoverage || [];
  const visibleAnalyses = analysisAccount === "all" ? data.statementAnalyses : data.statementAnalyses.filter((item: any) => item.accountId === analysisAccount || item.bankAccountId === analysisAccount || item.creditCardId === analysisAccount);
  const visibleDocuments = analysisAccount === "all" ? data.statementDocuments : data.statementDocuments.filter((item: any) => item.accountId === analysisAccount || item.bankAccountId === analysisAccount || item.creditCardId === analysisAccount || item.accountName === analysisAccounts.find((account: any) => account.id === analysisAccount)?.name);
  const screenshotDocuments = data.statementDocuments.filter((item: any) => item.sourceFormat === "screenshot");
  const selectedScreenshot = screenshotDocuments.find((item: any) => item.id === selectedScreenshotId) || screenshotDocuments[0];
  const allScreenshotTransactions = selectedScreenshot ? transactions.filter((item: any) => item.statementDocumentId === selectedScreenshot.id) : [];
  const screenshotTransactions = showConfirmedScreenshotRows ? allScreenshotTransactions : allScreenshotTransactions.filter((item: any) => !item.screenshotReviewConfirmedAt);
  const debitCategories = ["Internal transfer", "Salary / income", "Groceries", "Transport", "Fuel", "Dining & takeaway", "Household", "Utilities", "WiFi & mobile", "Insurance", "Medical", "Education", "Clothing", "Entertainment", "Cash withdrawal", "Bank fees", "Debt payment", "Savings & investment", "Charity / Zakah", "Other"];
  const creditCategories = ["Credit-card repayment", "Card purchase", "Groceries", "Transport", "Fuel", "Dining & takeaway", "Household", "Utilities", "WiFi & mobile", "Insurance", "Medical", "Education", "Clothing", "Entertainment", "Interest charge", "Card fee", "Refund", "Internal transfer", "Other"];
  const reviewCategories = reviewItem?.accountKind === "credit" ? creditCategories : debitCategories;
  const spending = data.spendingDashboard;
  const maxMonthlySpending = Math.max(1, ...(spending?.months || []).map((item: any) => item.netSpending));
  const maxCategorySpending = Math.max(1, ...(spending?.categories || []).map((item: any) => item.amount));
  return <div className="space-y-5">
    {reviewItem && <div className="fixed inset-0 z-50 bg-black/50 p-4 flex items-center justify-center" onMouseDown={event=>{if(event.target===event.currentTarget&&!categorySaving)setReviewItem(null);}}><div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto"><div className="p-5 border-b"><div className="flex items-start justify-between gap-4"><div><h3 className="font-semibold">Choose transaction category</h3><p className="text-xs text-stone-500 mt-1">{reviewItem.date} · {reviewItem.accountName}</p></div><button disabled={categorySaving} onClick={()=>setReviewItem(null)} className="text-stone-500 text-xl">×</button></div><div className="bg-stone-50 border rounded-xl p-3 mt-3"><strong className="text-sm break-words">{reviewItem.description}</strong><span className="block text-lg font-bold mt-1">{money.format(Number(reviewItem.amount))}</span>{reviewItem.suggestedCategory&&<span className="inline-block mt-2 text-[10px] bg-purple-100 text-purple-800 rounded-full px-2 py-1">AI suggests {reviewItem.suggestedCategory} · {Math.round(Number(reviewItem.aiConfidence||0)*100)}%</span>}</div></div><div className="p-5"><p className="text-[10px] uppercase font-bold text-stone-500 mb-2">Click once to classify and add</p><div className="grid grid-cols-2 sm:grid-cols-3 gap-2">{reviewCategories.map(category=><button key={category} disabled={categorySaving} onClick={()=>void applyCategory(category)} className={`border rounded-xl px-3 py-2.5 text-xs text-left hover:border-purple-400 hover:bg-purple-50 disabled:opacity-50 ${category===reviewItem.suggestedCategory?"border-purple-400 bg-purple-50 font-bold":"bg-white"}`}>{category}</button>)}</div><form onSubmit={event=>{event.preventDefault();void applyCategory(customCategory);}} className="flex gap-2 mt-4"><input value={customCategory} onChange={event=>setCustomCategory(event.target.value)} placeholder="Custom category" className="border rounded-lg px-3 py-2 text-sm flex-1"/><button disabled={categorySaving||!customCategory.trim()} className="bg-stone-900 text-white rounded-lg px-4 text-xs font-bold">Use custom</button></form><label className="flex items-start gap-2 mt-4 text-xs text-stone-600"><input type="checkbox" checked={rememberCategory} onChange={event=>setRememberCategory(event.target.checked)} disabled={reviewItem.suggestedCategory==="Internal transfer"} className="mt-0.5"/><span>Remember this merchant and automatically suggest this category on future statements. Internal transfers use their own protected rules.</span></label>{categorySaving&&<p className="text-xs text-purple-700 mt-3">Saving classification…</p>}</div></div></div>}
    <div className="flex gap-2 overflow-x-auto bg-purple-50 border border-purple-100 rounded-xl p-1">{[["spending","Spending dashboard"],["accounts","Account analysis"],["upload","Upload statement"],["balances","Balance screenshot"],["screenshots",`Screenshot review (${screenshotDocuments.length})`],["review",`Review (${pendingTransactions.length})`],["tools","Finance tools"]].map(([id,label])=><button key={id} onClick={()=>setInsightView(id as any)} className={`shrink-0 px-4 py-2 rounded-lg text-xs font-bold ${insightView===id?"bg-white shadow-sm text-purple-800":"text-stone-500"}`}>{label}</button>)}</div>
    {insightView === "spending" && spending && <>
      <section className="bg-white border rounded-2xl p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-semibold flex items-center gap-2"><BarChart3 className="h-4 w-4 text-purple-700"/>Monthly spending</h3><p className="text-xs text-stone-500 mt-1">Verified ledger totals. Transfers and loan proceeds are excluded; refunds reduce spending.</p><p className="text-[10px] text-stone-400 mt-1">{spending.expenseEntryCount} confirmed expense entries for {spending.currentMonth} · day {spending.elapsedDays} of {spending.daysInCurrentMonth} · refreshed {lifeOsDateTime.format(new Date(spending.generatedAt))}. Balance screenshots update account balances, not spending.</p></div><span className="text-[10px] uppercase font-bold bg-emerald-50 text-emerald-700 rounded-full px-3 py-1">Accounting-safe</span></div><div className="grid grid-cols-2 lg:grid-cols-5 gap-2 mt-4">{[["Net spending",spending.current.netSpending],["Income",spending.current.income],["Refunds",spending.current.refunds],["Projected month end",spending.projectedMonthEndSpending],[`${spending.completedBaselineMonths}-month normal`,spending.normalMonthlySpending]].map(([label,value])=><div key={String(label)} className="bg-stone-50 border rounded-xl p-3"><span className="block text-[10px] uppercase text-stone-500">{label}</span><strong className="block mt-1">{money.format(Number(value))}</strong></div>)}</div>{spending.normalMonthlySpending>0&&<p className={`text-xs mt-3 ${spending.differenceFromExpectedPace>0?"text-amber-700":"text-emerald-700"}`}>By day {spending.elapsedDays}, your usual pace would be {money.format(spending.expectedSpendingToDate)}. You are {money.format(Math.abs(spending.differenceFromExpectedPace))} {spending.differenceFromExpectedPace>0?"above":"below"} that pace.</p>}<div className="h-40 flex items-end gap-1.5 mt-5 border-b border-stone-200">{spending.months.map((item:any)=><div key={item.month} className="flex-1 min-w-0 text-center"><div title={`${item.month}: ${money.format(item.netSpending)}`} className={`rounded-t ${item.month===spending.currentMonth?"bg-purple-600":"bg-purple-200"}`} style={{height:`${Math.max(2,item.netSpending/maxMonthlySpending*120)}px`}}/><span className="block text-[9px] text-stone-500 mt-1">{item.month.slice(5)}{item.month.endsWith("-01")?` '${item.month.slice(2,4)}`:""}</span></div>)}</div></section>
      <section className="bg-white border rounded-2xl overflow-hidden"><div className="p-4 border-b flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-semibold">This week’s transaction history</h3><p className="text-xs text-stone-500 mt-1">{spending.week.start} to {spending.week.end} · newest transactions first · confirmed ledger entries</p></div><div className="flex gap-2 text-[10px]"><span className="bg-red-50 text-red-700 rounded-full px-2 py-1">Spent {money.format(spending.week.summary.spending)}</span><span className="bg-emerald-50 text-emerald-700 rounded-full px-2 py-1">Income {money.format(spending.week.summary.income)}</span></div></div><div className="max-h-96 overflow-y-auto divide-y">{spending.week.transactions.map((item:any)=><div key={item.id} className="p-3 grid grid-cols-[76px_minmax(0,1fr)_auto] md:grid-cols-[100px_minmax(180px,1fr)_170px_130px] gap-2 items-center text-xs"><span className="text-stone-500">{item.date}</span><div className="min-w-0"><strong className="block truncate" title={item.description}>{item.description}</strong><span className="block truncate text-[10px] text-stone-500">{item.category} · {item.accountName}</span></div><span className={`hidden md:inline-flex w-fit rounded-full px-2 py-1 text-[9px] uppercase font-bold ${item.type==="expense"?"bg-red-50 text-red-700":item.type==="income"||item.type==="refund"?"bg-emerald-50 text-emerald-700":"bg-blue-50 text-blue-700"}`}>{item.type.replaceAll("-"," ")}</span><strong className={`text-right ${item.type==="expense"?"text-red-700":item.type==="income"||item.type==="refund"?"text-emerald-700":"text-blue-700"}`}>{item.type==="expense"?"−":item.type==="income"||item.type==="refund"?"+":""}{money.format(item.amount)}</strong></div>)}{!spending.week.transactions.length&&<p className="p-6 text-sm text-stone-500 text-center">No confirmed transactions are recorded for this week yet.</p>}</div></section>
      <div className="grid lg:grid-cols-2 gap-5"><section className="bg-white border rounded-2xl p-5"><h3 className="font-semibold">Spending by category</h3><div className="mt-4 space-y-3 max-h-80 overflow-y-auto">{spending.categories.map((item:any)=><div key={item.name}><div className="flex justify-between gap-3 text-xs"><span className="truncate">{item.name}</span><strong>{money.format(item.amount)}</strong></div><div className="h-2 bg-stone-100 rounded-full mt-1"><div className="h-full bg-blue-500 rounded-full" style={{width:`${item.amount/maxCategorySpending*100}%`}}/></div></div>)}{!spending.categories.length&&<p className="text-xs text-stone-500">No spending is recorded for this month yet.</p>}</div></section><section className="bg-white border rounded-2xl p-5"><h3 className="font-semibold">Top merchants and accounts</h3><div className="grid sm:grid-cols-2 gap-4 mt-4"><div><h4 className="text-[10px] uppercase font-bold text-stone-500">Merchants</h4><div className="space-y-2 mt-2">{spending.merchants.slice(0,6).map((item:any)=><div key={item.name} className="flex justify-between gap-2 text-xs"><span className="truncate" title={item.name}>{item.name}</span><strong className="shrink-0">{money.format(item.amount)}</strong></div>)}</div></div><div><h4 className="text-[10px] uppercase font-bold text-stone-500">Accounts</h4><div className="space-y-2 mt-2">{spending.accounts.map((item:any)=><div key={item.id} className="bg-stone-50 rounded-lg p-2 text-xs"><strong className="block truncate">{item.name}</strong><span>{item.kind} · {money.format(item.spending)}</span></div>)}{!spending.accounts.length&&<p className="text-xs text-stone-500">No linked account spending this month.</p>}</div></div></div></section></div>
      <section className="grid grid-cols-3 gap-2 bg-emerald-50 border border-emerald-200 rounded-xl p-3 text-[10px] text-emerald-900"><span>✓ Transfers excluded</span><span>✓ Loan proceeds excluded from income</span><span>✓ Refunds offset spending</span></section>
      {data.financeVerification&&<section className="bg-white border rounded-2xl p-5"><div className="flex flex-wrap justify-between gap-3"><div><h3 className="font-semibold flex items-center gap-2"><ShieldCheck className="h-4 w-4 text-emerald-700"/>Data truth and coverage</h3><p className="text-xs text-stone-500 mt-1">Statement-backed records are separated from manual snapshots and lower-confidence classifications.</p></div><span className="bg-stone-900 text-white rounded-full px-3 py-1 text-xs font-bold">{data.financeVerification.score}% verified</span></div><div className="grid md:grid-cols-3 gap-2 mt-4">{data.financeVerification.coverage.map((item:any)=><div key={item.id} className="border rounded-xl p-3 text-xs"><div className="flex justify-between gap-2"><strong className="truncate">{item.name}</strong><span className={`rounded-full px-2 py-0.5 text-[9px] uppercase ${item.balanceStatus==="current"?"bg-emerald-50 text-emerald-700":"bg-amber-50 text-amber-700"}`}>{item.balanceStatus} balance</span></div><span className="block text-stone-500 mt-2">{item.transactions} rows · {item.statements} statement{item.statements===1?"":"s"}</span><span className="block mt-1">{item.firstTransaction&&item.lastTransaction?`${item.firstTransaction} to ${item.lastTransaction}`:"No statement coverage"}</span>{item.missingMonths.length>0?<span className="block text-amber-700 mt-1">Missing months: {item.missingMonths.join(", ")}</span>:item.months.length>0&&<span className="block text-emerald-700 mt-1">No gaps inside saved range</span>}</div>)}</div><details className="border rounded-xl mt-4 overflow-hidden"><summary className="cursor-pointer p-3 text-xs font-bold bg-stone-50">Verification queue · {data.financeVerification.verificationQueue.length}</summary><div className="max-h-72 overflow-y-auto divide-y">{data.financeVerification.verificationQueue.map((item:any)=><div key={item.id} className="p-3 text-xs"><div className="flex justify-between gap-3"><strong className="truncate">{item.description}</strong><span className="shrink-0">{money.format(item.amount)}</span></div><span className="block text-stone-500 mt-1">{item.date} · {item.category} · {item.reason}{item.confidence!==null?` (${Math.round(item.confidence*100)}%)`:""}</span></div>)}{!data.financeVerification.verificationQueue.length&&<p className="p-4 text-emerald-700 text-xs">Every record is statement-backed or explicitly verified.</p>}</div></details></section>}
    </>}
    {insightView === "upload" && <><section className="rounded-2xl border-2 border-purple-300 bg-purple-50 p-5"><label className="block text-sm font-bold text-purple-950">1. Which account does this image or statement belong to?</label><p className="mt-1 text-xs text-purple-700">All extracted transactions, balance corrections, analysis, and AI memory will be attached to this account.</p><select required value={accountId} onChange={e=>setAccountId(e.target.value)} className="mt-3 w-full rounded-xl border border-purple-300 bg-white p-3 text-sm font-semibold"><option value="">Select the correct account before uploading</option>{accounts.length>0&&<optgroup label="My debit accounts">{accounts.map(x=><option key={x.id} value={`debit:${x.id}`}>{x.name} — debit account</option>)}</optgroup>}<optgroup label="My credit account">{cards.map(x=><option key={x.id} value={`credit:${x.id}`}>{x.name} — credit account</option>)}</optgroup></select>{accountId&&<p className="mt-3 rounded-lg bg-white p-2 text-xs font-bold text-emerald-700">Selected: {[...accounts,...cards].find(item=>item.id===accountId.split(":")[1])?.name} ({accountId.startsWith("credit:")?"credit":"debit"})</p>}</section><label className={`block rounded-2xl border-2 border-dashed p-5 ${accountId?"cursor-pointer border-blue-300 bg-blue-50":"cursor-not-allowed border-stone-200 bg-stone-50 opacity-60"}`}><span className="font-semibold flex items-center gap-2"><FileUp className="h-5 w-5 text-blue-700"/>2. Upload transaction screenshot, PDF, or CSV</span><span className="block text-xs text-stone-600 mt-1">Screenshots are read locally with Apple Vision OCR. Extracted transactions are saved permanently, checked for duplicates, classified by AI, and kept in the approval queue before affecting your ledger.</span><input disabled={!accountId} type="file" accept=".csv,.pdf,.png,.jpg,.jpeg,.heic,.heif,text/csv,application/pdf,image/*" onChange={loadStatementFile} className="block mt-3 text-sm"/>{fileName && <span className="block text-xs text-emerald-700 mt-2">{fileName} is assigned to {[...accounts,...cards].find(item=>item.id===accountId.split(":")[1])?.name}. Select Analyze and save below.</span>}</label>
    <div className="grid lg:grid-cols-2 gap-5"><form onSubmit={saveStatement} className="bg-white border rounded-2xl p-5 space-y-2"><h3 className="font-semibold">Credit-card statement</h3><select required value={statement.liabilityId} onChange={e=>setStatement({...statement,liabilityId:e.target.value})} className="border rounded-lg p-2 w-full"><option value="">Choose card</option>{cards.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select><div className="grid grid-cols-2 gap-2"><input type="date" required value={statement.statementDate} onChange={e=>setStatement({...statement,statementDate:e.target.value})} className="border rounded-lg p-2"/><input type="date" required value={statement.dueDate} onChange={e=>setStatement({...statement,dueDate:e.target.value})} className="border rounded-lg p-2"/><input type="number" step=".01" required value={statement.statementBalance} onChange={e=>setStatement({...statement,statementBalance:e.target.value})} placeholder="Statement balance" className="border rounded-lg p-2"/><input type="number" step=".01" required value={statement.minimumDue} onChange={e=>setStatement({...statement,minimumDue:e.target.value})} placeholder="Minimum due" className="border rounded-lg p-2"/></div><button className="bg-stone-900 text-white px-4 py-2 rounded-lg text-xs">Save statement</button></form><form onSubmit={importCsv} className="bg-white border rounded-2xl p-5 space-y-2"><h3 className="font-semibold flex gap-2"><Sparkles className="h-4 w-4 text-purple-700"/>AI transaction import</h3><p className="text-xs text-stone-500">Choose which debit or credit account these transactions belong to.</p><select required value={accountId} onChange={e=>setAccountId(e.target.value)} className="border rounded-lg p-2 w-full"><option value="">Choose debit or credit account</option>{accounts.length > 0 && <optgroup label="Debit accounts">{accounts.map(x=><option key={x.id} value={`debit:${x.id}`}>{x.name}</option>)}</optgroup>}<optgroup label="Credit account">{cards.map(x=><option key={x.id} value={`credit:${x.id}`}>{x.name}</option>)}</optgroup></select>{accounts.length === 0 && <p className="text-xs text-amber-700">No debit accounts are saved yet. Add both below; each will then appear here.</p>}{accountId.startsWith("credit:") && <label className="flex gap-2 items-start text-xs bg-amber-50 border border-amber-200 rounded-lg p-3"><input type="checkbox" checked={positiveCreditMeansSpending} onChange={e=>setPositiveCreditMeansSpending(e.target.checked)} className="mt-0.5"/><span>Positive amounts on this credit statement are purchases/charges. Turn this off if your statement records purchases as negative amounts.</span></label>}{imageBase64 ? <div className="bg-blue-50 border border-blue-200 rounded-lg p-3 text-xs"><strong>Screenshot ready:</strong> {fileName}<br/>Keep dates, merchant names, and amounts visible together for the best result.</div> : pdfBase64 ? <div className="bg-purple-50 border border-purple-200 rounded-lg p-3 text-xs"><strong>PDF ready:</strong> {fileName}<br/>LifeOS will extract transaction rows locally, then NVIDIA will analyze them.</div> : <textarea required={!pdfBase64&&!imageBase64} rows={4} value={csv} onChange={e=>{setCsv(e.target.value); setFileName("pasted-statement.csv");}} placeholder={'date,description,amount\n2026-07-15,Example,-100'} className="border rounded-lg p-2 w-full text-xs font-mono"/>}<button disabled={analyzing || (!csv.trim() && !pdfBase64 && !imageBase64)} className="bg-purple-700 text-white px-4 py-2 rounded-lg text-xs disabled:opacity-50">{analyzing ? "Reading, extracting, and classifying…" : "Analyze and save"}</button></form></div>
    {accounts.length < 2 && <form onSubmit={addDebitAccount} className="bg-emerald-50 border border-emerald-200 rounded-2xl p-5"><h3 className="font-semibold">Add debit account {accounts.length + 1} of 2</h3><p className="text-xs text-stone-600 mt-1">Use the real account name and current available balance. LifeOS never asks for account numbers, PINs, or banking passwords.</p><div className="grid md:grid-cols-3 gap-2 mt-3"><input required value={newDebit.name} onChange={e=>setNewDebit({...newDebit,name:e.target.value})} placeholder="Account name" className="border rounded-lg p-2"/><input value={newDebit.institution} onChange={e=>setNewDebit({...newDebit,institution:e.target.value})} placeholder="Bank name" className="border rounded-lg p-2"/><input required type="number" step=".01" value={newDebit.balance} onChange={e=>setNewDebit({...newDebit,balance:e.target.value})} placeholder="Current balance (R)" className="border rounded-lg p-2"/></div><button className="mt-3 bg-emerald-700 text-white rounded-lg px-4 py-2 text-xs font-bold">Save debit account</button></form>}</>}
    {insightView === "balances" && <section className="bg-white border rounded-2xl p-5"><div className="flex items-start gap-3"><div className="rounded-xl bg-emerald-100 p-3"><FileUp className="h-5 w-5 text-emerald-700"/></div><div><h3 className="font-semibold">Upload all account balances</h3><p className="text-xs text-stone-500 mt-1">Use a banking overview screenshot showing your debit balances and credit-card totals. AI matches visible balances to saved accounts, then you review every value before anything changes.</p></div></div><div className="mt-4 rounded-xl border-2 border-dashed border-emerald-300 bg-emerald-50 p-4"><input type="file" accept="image/png,image/jpeg,image/heic,image/heif,.png,.jpg,.jpeg,.heic,.heif" onChange={loadBalanceScreenshot} className="text-sm"/>{balanceImageName&&<p className="mt-2 text-xs text-emerald-800">Ready: {balanceImageName}</p>}<button type="button" disabled={!balanceImageBase64||balanceAnalyzing} onClick={()=>void analyzeBalances()} className="mt-3 rounded-lg bg-emerald-700 px-4 py-2 text-xs font-bold text-white disabled:opacity-50">{balanceAnalyzing?"Reading all balances…":"Analyze balance screenshot"}</button></div>{balanceProposals.length>0&&<div className="mt-5"><div className="flex flex-wrap items-center justify-between gap-2"><div><h4 className="text-sm font-semibold">Review detected balances</h4><p className="text-xs text-amber-700">Check each amount and date carefully. Debit values are available cash; credit values are amounts owed.</p></div><button type="button" disabled={balanceAnalyzing} onClick={()=>void confirmBalances()} className="rounded-lg bg-stone-900 px-4 py-2 text-xs font-bold text-white disabled:opacity-50">Confirm and sync all finance</button></div><div className="mt-3 space-y-2">{balanceProposals.map((proposal,index)=><div key={proposal.id} className="grid gap-2 rounded-xl border p-3 md:grid-cols-[1fr_150px_150px_150px]"><div><strong className="text-sm">{proposal.accountName}</strong><span className="block text-[10px] uppercase text-stone-500">{proposal.accountKind} · AI {Math.round(Number(proposal.confidence||0)*100)}%</span></div><label className="text-[10px] text-stone-500">{proposal.accountKind==="credit"?"Amount owed":"Available balance"}<input type="number" step=".01" value={proposal.balance} onChange={event=>setBalanceProposals(rows=>rows.map((row,i)=>i===index?{...row,balance:event.target.value}:row))} className="mt-1 w-full rounded-lg border p-2 text-sm text-stone-900"/></label>{proposal.accountKind==="credit"?<label className="text-[10px] text-stone-500">Credit limit<input type="number" step=".01" value={proposal.creditLimit??""} onChange={event=>setBalanceProposals(rows=>rows.map((row,i)=>i===index?{...row,creditLimit:event.target.value}:row))} className="mt-1 w-full rounded-lg border p-2 text-sm text-stone-900"/></label>:<div/>}<label className="text-[10px] text-stone-500">Balance date<input type="date" value={proposal.asOfDate} onChange={event=>setBalanceProposals(rows=>rows.map((row,i)=>i===index?{...row,asOfDate:event.target.value}:row))} className="mt-1 w-full rounded-lg border p-2 text-sm text-stone-900"/></label></div>)}</div></div>}{data.balanceScreenshotDocuments?.length>0&&<details className="mt-5 rounded-xl border p-3"><summary className="cursor-pointer text-xs font-bold">Saved balance screenshots · {data.balanceScreenshotDocuments.length}</summary><div className="mt-2 space-y-2">{data.balanceScreenshotDocuments.slice(0,8).map((document:any)=><div key={document.id} className="flex justify-between gap-3 text-xs"><span className="truncate">{document.originalFileName}</span><span className="shrink-0 text-stone-500">{document.status} · {lifeOsDateTime.format(new Date(document.createdAt))}</span></div>)}</div></details>}</section>}
    {insightView === "balances" && data.balanceScreenshotDocuments?.length>0 && <section className="bg-white border rounded-2xl p-4"><h3 className="text-sm font-semibold">Manage saved balance screenshots</h3><p className="mt-1 text-xs text-stone-500">Remove incorrect or outdated screenshots. Confirmed financial balances are never reversed automatically.</p><div className="mt-3 max-h-64 space-y-2 overflow-y-auto">{data.balanceScreenshotDocuments.map((document:any)=><div key={document.id} className="flex items-center justify-between gap-3 rounded-xl border p-3"><div className="min-w-0"><strong className="block truncate text-xs">{document.originalFileName}</strong><span className="text-[10px] text-stone-500">{document.status} · {lifeOsDateTime.format(new Date(document.createdAt))}</span></div><button type="button" onClick={()=>void removeBalanceScreenshot(document)} className="shrink-0 rounded-lg border border-red-200 px-3 py-2 text-[10px] font-bold text-red-700 hover:bg-red-50">Remove</button></div>)}</div></section>}
    {insightView === "screenshots" && <>
      <section className="bg-white border rounded-2xl p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-semibold">Uploaded screenshot review</h3><p className="text-xs text-stone-500 mt-1">Choose an image, correct every extracted row, and confirm the real account balance separately.</p><p className="text-[10px] text-blue-700 mt-1">LifeOS time: {lifeOsDateTime.format(new Date())} · Africa/Johannesburg</p></div><select value={selectedScreenshot?.id||""} onChange={event=>setSelectedScreenshotId(event.target.value)} className="border rounded-lg p-2 text-xs max-w-full"><option value="">Choose screenshot</option>{screenshotDocuments.map((document:any)=><option key={document.id} value={document.id}>{document.accountName} · {document.originalFileName} · uploaded {lifeOsDateTime.format(new Date(document.createdAt))}</option>)}</select></div></section>
      {!selectedScreenshot ? <div className="bg-white border rounded-xl p-6 text-sm text-stone-500">No transaction screenshots have been uploaded yet.</div> : <>
        <section className="grid lg:grid-cols-[1fr_360px] gap-4"><div className="bg-blue-50 border border-blue-200 rounded-2xl p-4"><h3 className="font-semibold text-blue-950">{selectedScreenshot.accountName}</h3><p className="text-xs text-blue-800 mt-1 break-all">{selectedScreenshot.originalFileName}</p><div className="grid grid-cols-3 gap-2 mt-3 text-xs"><div className="bg-white rounded-lg p-2"><span className="block text-stone-500">To review</span><strong>{allScreenshotTransactions.filter((item:any)=>!item.screenshotReviewConfirmedAt).length}</strong></div><div className="bg-white rounded-lg p-2"><span className="block text-stone-500">Status</span><strong>{selectedScreenshot.status}</strong></div><div className="bg-white rounded-lg p-2"><span className="block text-stone-500">Balance</span><strong>{selectedScreenshot.balanceStatus||"not visible"}</strong></div></div><p className="text-xs text-blue-900 mt-3">{selectedScreenshot.imageSummary}</p></div><form onSubmit={confirmScreenshotBalance} className="bg-amber-50 border border-amber-200 rounded-2xl p-4"><h3 className="font-semibold text-amber-950">Correct main balance</h3><p className="text-xs text-amber-800 mt-1">Transaction screenshots cannot change the main balance unless an actual balance is visible. Enter the current balance shown by your bank.</p><div className="grid grid-cols-2 gap-2 mt-3"><input required type="number" step=".01" value={balanceConfirm.balance} onChange={event=>setBalanceConfirm({...balanceConfirm,balance:event.target.value})} placeholder="Balance (R)" className="border rounded-lg p-2 text-sm"/><input required type="date" value={balanceConfirm.balanceAsOf} onChange={event=>setBalanceConfirm({...balanceConfirm,balanceAsOf:event.target.value})} className="border rounded-lg p-2 text-sm"/></div><button disabled={screenshotSaving==="balance"||!balanceConfirm.balance} className="mt-3 bg-amber-700 text-white rounded-lg px-4 py-2 text-xs font-bold disabled:opacity-50">{screenshotSaving==="balance"?"Updating…":"Update main balance"}</button></form></section>
        <section className="bg-white border rounded-2xl overflow-hidden"><div className="p-4 border-b flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-semibold">Transactions extracted from this screenshot</h3><p className="text-xs text-stone-500 mt-1">Saving removes a row from this active list. Confirmed rows remain permanently available.</p></div><button onClick={()=>setShowConfirmedScreenshotRows(value=>!value)} className="border rounded-lg px-3 py-2 text-xs font-bold">{showConfirmedScreenshotRows?"Hide confirmed":`Show confirmed (${allScreenshotTransactions.filter((item:any)=>item.screenshotReviewConfirmedAt).length})`}</button></div><div className="max-h-[620px] overflow-auto divide-y">{screenshotTransactions.map((item:any)=>{const draft=screenshotDrafts[item.id]||{date:item.date,description:item.description,amount:item.analysisAmount??item.amount,category:item.suggestedCategory||"Other"};const update=(changes:any)=>setScreenshotDrafts(current=>({...current,[item.id]:{...draft,...changes}}));return <div key={item.id} className="p-3 grid md:grid-cols-[130px_minmax(220px,1fr)_130px_190px_auto] gap-2 items-center"><input type="date" value={draft.date} onChange={event=>update({date:event.target.value})} className="border rounded-lg p-2 text-xs"/><input value={draft.description} onChange={event=>update({description:event.target.value})} className="border rounded-lg p-2 text-xs min-w-0"/><input type="number" step=".01" value={draft.amount} onChange={event=>update({amount:event.target.value})} className="border rounded-lg p-2 text-xs"/><input value={draft.category} onChange={event=>update({category:event.target.value})} className="border rounded-lg p-2 text-xs"/><div className="flex items-center gap-2"><span className={`rounded-full px-2 py-1 text-[9px] font-bold ${item.status==="reconciled"?"bg-emerald-50 text-emerald-700":"bg-amber-50 text-amber-700"}`}>{item.status==="reconciled"?"Added":"Needs approval"}</span><button onClick={()=>void saveScreenshotRow(item)} disabled={screenshotSaving===item.id} className="bg-stone-900 text-white rounded-lg px-3 py-2 text-[10px] font-bold disabled:opacity-50">{screenshotSaving===item.id?"Saving…":"Save & confirm"}</button></div></div>})}{!screenshotTransactions.length&&<p className="p-6 text-sm text-emerald-700 text-center">All transactions from this screenshot have been reviewed.</p>}</div></section>
      </>}
    </>}
    {insightView === "accounts" && <>
    <section className="bg-stone-900 text-white rounded-2xl p-5"><div className="flex flex-wrap justify-between gap-3"><div><h3 className="font-semibold flex items-center gap-2"><Sparkles className="h-4 w-4 text-emerald-400"/>Consolidated AI finance briefing</h3><p className="text-xs text-stone-400 mt-1">One NVIDIA review across every saved account, debt, bill, and detected pattern.</p></div><button onClick={createBriefing} disabled={briefingLoading} className="bg-emerald-400 text-stone-950 rounded-lg px-4 py-2 text-xs font-bold disabled:opacity-50">{briefingLoading?"Analyzing all records…":data.latestAiBriefing?"Refresh briefing":"Create briefing"}</button></div>{data.latestAiBriefing?<div className="mt-4"><div className="text-[10px] uppercase text-stone-400">{data.latestAiBriefing.provider} · {new Date(data.latestAiBriefing.createdAt).toLocaleString("en-ZA")} · {data.latestAiBriefing.basedOn.transactions} transactions · {data.latestAiBriefing.basedOn.pendingReview} pending</div><div className="mt-3 text-sm"><MarkdownMessage content={data.latestAiBriefing.summary}/></div><div className="grid md:grid-cols-2 gap-3 mt-4">{[["Priorities",data.latestAiBriefing.priorities],["Next actions",data.latestAiBriefing.nextActions],["Spending findings",data.latestAiBriefing.spendingFindings],["Risks",data.latestAiBriefing.risks]].map(([label,items]:any)=><details key={label} className="bg-stone-800 rounded-xl p-3"><summary className="cursor-pointer text-xs font-bold">{label} · {items?.length||0}</summary>{items?.length>0&&<ul className="list-disc pl-5 mt-2 text-xs text-stone-300 space-y-1">{items.map((item:string)=><li key={item}>{item}</li>)}</ul>}</details>)}</div></div>:<p className="text-sm text-stone-300 mt-4">Create the first briefing to turn your combined finance records into prioritized actions. Nothing is changed without your approval.</p>}</section>
    {data.statementAnalyses?.length > 0 && <section className="bg-gradient-to-br from-purple-50 to-white border border-purple-200 rounded-2xl p-5"><div><h3 className="font-semibold flex gap-2"><Sparkles className="h-4 w-4 text-purple-700"/>AI analysis by account</h3><p className="text-xs text-stone-500 mt-1">Statements and findings stay attached to the account selected during upload.</p></div><div className="flex gap-2 overflow-x-auto mt-4 pb-1"><button onClick={()=>setAnalysisAccount("all")} className={`shrink-0 rounded-full px-3 py-2 text-xs font-bold border ${analysisAccount==="all"?"bg-purple-700 text-white border-purple-700":"bg-white"}`}>All accounts</button>{analysisAccounts.map((account:any)=><button key={account.id} onClick={()=>setAnalysisAccount(account.id)} className={`shrink-0 rounded-full px-3 py-2 text-xs font-bold border ${analysisAccount===account.id?"bg-purple-700 text-white border-purple-700":"bg-white"}`}>{account.name} · {account.transactions}</button>)}</div><div className="grid md:grid-cols-3 gap-2 mt-4">{analysisAccounts.filter((account:any)=>analysisAccount==="all"||account.id===analysisAccount).map((account:any)=><div key={account.id} className="bg-white border rounded-xl p-3 text-xs"><strong>{account.name}</strong><span className="block text-stone-500 mt-1">{account.kind} · {account.transactions} transactions</span><span className="block mt-2">Outflows {money.format(account.spending)}<br/>Inflows {money.format(account.inflows)}</span></div>)}</div><div className="space-y-3 mt-4">{visibleAnalyses.map((analysis:any)=><details key={analysis.id} open={visibleAnalyses.length===1} className="bg-white border rounded-xl overflow-hidden"><summary className="cursor-pointer p-4 list-none flex flex-wrap justify-between gap-2"><div><strong className="text-sm">{analysis.accountName}</strong><span className="block text-xs text-stone-500">{analysis.sourceFileName} · {analysis.importedCount} transactions · {new Date(analysis.createdAt).toLocaleDateString("en-ZA")}</span></div><span className="text-[10px] uppercase text-purple-700">{analysis.provider}</span></summary><div className="border-t p-4"><div className="grid grid-cols-2 gap-2 mb-3"><div className="bg-stone-50 rounded-lg p-3 text-xs"><span className="text-stone-500">Outflows</span><strong className="block">{money.format(analysis.totalSpending)}</strong></div><div className="bg-stone-50 rounded-lg p-3 text-xs"><span className="text-stone-500">Inflows / repayments</span><strong className="block">{money.format(analysis.totalIncome)}</strong></div></div><div className="text-sm"><MarkdownMessage content={analysis.summary}/></div>{analysis.patterns?.length>0&&<div className="mt-3"><h4 className="text-xs font-bold uppercase text-stone-500">Patterns</h4><ul className="list-disc pl-5 text-sm mt-1">{analysis.patterns.map((item:string)=><li key={item}>{item}</li>)}</ul></div>}{analysis.concerns?.length>0&&<div className="mt-3 bg-amber-50 rounded-lg p-3"><h4 className="text-xs font-bold uppercase text-amber-800">Watch closely</h4><ul className="list-disc pl-5 text-sm mt-1">{analysis.concerns.map((item:string)=><li key={item}>{item}</li>)}</ul></div>}{analysis.recommendations?.length>0&&<div className="mt-3"><h4 className="text-xs font-bold uppercase text-emerald-700">Recommendations</h4><ol className="list-decimal pl-5 text-sm mt-1">{analysis.recommendations.map((item:string)=><li key={item}>{item}</li>)}</ol></div>}</div></details>)}{!visibleAnalyses.length&&<p className="text-sm text-stone-500 bg-white border rounded-xl p-4">No analyzed statement is attached to this account yet.</p>}</div>{visibleDocuments.length>0&&<div className="mt-4"><h4 className="text-xs font-bold uppercase text-stone-500">Saved statement files</h4><div className="grid md:grid-cols-2 gap-2 mt-2">{visibleDocuments.map((document:any)=><div key={document.id} className="bg-white border rounded-xl p-3"><strong className="text-xs break-all">{document.originalFileName}</strong><span className="block text-[11px] text-stone-500 mt-1">{document.accountName} · {document.pages} pages</span><span className="inline-block mt-2 text-[9px] uppercase font-bold bg-emerald-50 text-emerald-700 rounded-full px-2 py-1">{document.status.replaceAll("-"," ")}</span></div>)}</div></div>}</section>}
    {data.transactionIntelligence && <section className="bg-white border rounded-2xl p-5"><div className="flex flex-wrap justify-between gap-3"><div><h3 className="font-semibold flex gap-2"><Sparkles className="h-4 w-4 text-blue-700"/>Transaction intelligence</h3><p className="text-xs text-stone-500 mt-1">Consolidated evidence-based checks across each saved debit and credit account.</p></div><span className="text-[10px] uppercase font-bold bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-full px-3 py-1 h-fit">Duplicate protection on</span></div><div className="grid grid-cols-2 md:grid-cols-4 gap-2 mt-4">{[["Saved",data.transactionIntelligence.quality.savedTransactions],["Awaiting review",data.transactionIntelligence.quality.pendingReview],["Learned",data.transactionIntelligence.quality.learnedMatches],["Transfers",data.transactionIntelligence.quality.transferMatches]].map(([label,value])=><div key={String(label)} className="bg-stone-50 border rounded-xl p-3"><span className="block text-[10px] uppercase text-stone-500">{label}</span><strong>{value}</strong></div>)}</div><div className="grid md:grid-cols-3 gap-2 mt-4">{data.transactionIntelligence.accountCoverage.map((account:any)=><div key={account.id} className="border rounded-xl p-3 text-xs"><strong>{account.name}</strong><span className="block text-stone-500 mt-1">{account.kind} · {account.transactions} transactions</span><span className="block mt-2">Outflows {money.format(account.spending)} · Inflows {money.format(account.inflows)}</span></div>)}</div><div className="grid lg:grid-cols-2 gap-4 mt-4"><div className="border rounded-xl p-4"><h4 className="text-sm font-semibold">Likely recurring payments</h4><div className="mt-2 max-h-64 overflow-y-auto space-y-2">{data.transactionIntelligence.recurring.map((item:any)=><div key={`${item.merchantKey}-${item.accountId}`} className="bg-blue-50 rounded-lg p-2 text-xs"><strong className="block truncate">{item.merchant}</strong><span>{money.format(item.typicalAmount)} typical · {item.occurrences} occurrences · {Math.round(item.confidence*100)}% pattern</span></div>)}{!data.transactionIntelligence.recurring.length&&<p className="text-xs text-stone-500">More statement history is needed to confirm stable recurring patterns.</p>}</div></div><div className="border rounded-xl p-4"><h4 className="text-sm font-semibold">Unusual spending to review</h4><div className="mt-2 max-h-64 overflow-y-auto space-y-2">{data.transactionIntelligence.unusual.map((item:any)=><div key={item.transactionId} className="bg-amber-50 rounded-lg p-2 text-xs"><strong className="block truncate">{item.merchant}</strong><span>{money.format(item.amount)} on {item.date} · {item.multiple}× its usual amount</span></div>)}{!data.transactionIntelligence.unusual.length&&<p className="text-xs text-emerald-700">No strong merchant-level anomalies detected.</p>}</div></div></div></section>}</>}
    {insightView === "tools" && <>
    <section className="bg-white border rounded-2xl p-5"><h3 className="font-semibold flex gap-2"><AlertTriangle className="h-4 w-4 text-amber-600"/>Payment reminders</h3><div className="grid md:grid-cols-2 gap-2 mt-3">{data.reminders.map((x: any) => <div key={x.id} className={`border rounded-xl p-3 text-sm ${x.status === "overdue" ? "bg-red-50" : x.status === "due-soon" ? "bg-amber-50" : "bg-stone-50"}`}><strong>{x.name}</strong><small className="block">{money.format(x.amount)} · {x.days < 0 ? `${-x.days} days overdue` : `due in ${x.days} days`} · {x.dueDate}</small></div>)}{!data.reminders.length && <p className="text-sm text-emerald-700">Nothing due in 30 days.</p>}</div><p className="text-[11px] text-stone-500 mt-3">Recurring due dates automatically roll forward when they pass.</p></section>
    <section className="bg-white border rounded-2xl p-5"><h3 className="font-semibold flex gap-2"><BarChart3 className="h-4 w-4 text-purple-700"/>Payoff estimates and what-if scenarios</h3><p className="text-xs text-stone-500 mt-2">Uses recorded balances, annual rates and constant payments. Lender fees may change actual results.</p><div className="overflow-x-auto mt-3"><table className="w-full text-sm"><thead><tr className="text-left border-b"><th>Debt</th><th>Minimum</th><th>+ R500</th><th>+ R1,000</th></tr></thead><tbody>{data.projections.map((row: any) => <tr key={row.id} className="border-b"><td className="py-3"><strong>{row.name}</strong><small className="block">{money.format(row.balance)} · {row.interestRate}%</small></td>{[row.base,row.extra500,row.extra1000].map((s: any,i: number) => <td key={i}><strong>{s.payoffDate || "Payment too low"}</strong>{s.feasible && <small className="block">{s.months} months · {money.format(s.totalInterest)} interest</small>}</td>)}</tr>)}</tbody></table></div></section>
    <div className="grid lg:grid-cols-2 gap-5"><section className="bg-white border rounded-2xl p-5"><h3 className="font-semibold flex gap-2"><ShieldCheck className="h-4 w-4 text-emerald-700"/>Emergency-fund protection</h3><p className="text-sm mt-3">Bank cash: <strong>{money.format(data.emergencyFund.currentCash)}</strong><br/>Safe above reserve: <strong>{money.format(data.emergencyFund.safeExtraCash)}</strong></p><div className="flex gap-2 mt-3"><input type="number" min="0" value={reserve} onChange={e => setReserve(e.target.value)} placeholder="Reserve target" className="border rounded-lg p-2 flex-1"/><button onClick={saveReserve} className="bg-stone-900 text-white rounded-lg px-4 text-xs">Save</button></div>{data.emergencyFund.protected && <p className="text-xs text-amber-700 mt-2">Avoid extra payments until this reserve is restored.</p>}</section><section className="bg-white border rounded-2xl p-5"><h3 className="font-semibold">Credit utilization</h3>{data.cards.map((x: any) => <div key={x.id} className="mt-3"><div className="flex justify-between text-sm"><strong>{x.name}</strong><span>{x.utilization === null ? "Limit missing" : `${x.utilization}% used`}</span></div><div className="h-3 bg-stone-100 rounded mt-1"><div className={`${x.warning ? "bg-amber-500" : "bg-emerald-500"} h-full rounded`} style={{width:`${Math.min(100,x.utilization || 0)}%`}}/></div></div>)}</section></div>
    <section className="bg-white border rounded-2xl p-5"><h3 className="font-semibold">12-month payment progress</h3><div className="h-36 flex items-end gap-2 mt-3">{data.history.map((x: any) => <div key={x.month} className="flex-1 text-center"><div title={money.format(x.paid)} className="bg-blue-500 rounded-t" style={{height:`${Math.max(2,x.paid/maxPaid*105)}px`}}/><small>{x.month.slice(5)}</small></div>)}</div></section></>}
    {insightView === "review" && (pendingTransactions.length > 0 ? <section className="bg-white border rounded-2xl overflow-hidden"><button type="button" onClick={()=>setApprovalOpen(value=>!value)} className="w-full p-5 flex items-center justify-between gap-3 text-left hover:bg-stone-50"><div><h3 className="font-semibold">AI classifications awaiting approval</h3><p className="text-xs text-stone-500 mt-1">{pendingTransactions.length} saved · {learnedClassifications} learned merchant matches · {transferCandidates} transfer matches</p></div><span className="bg-purple-100 text-purple-800 rounded-full px-3 py-1 text-xs font-bold">{approvalOpen ? "Collapse" : "Review"}</span></button>{approvalOpen && <div className="border-t"><div className="p-4 bg-stone-50 sticky top-0 z-10"><div className="flex flex-wrap gap-2 mb-3">{transferCandidates>0&&<button onClick={()=>bulkReconcile("cross-account-match",transferCandidates)} className="bg-blue-700 text-white rounded-lg px-3 py-2 text-xs font-bold">Approve {transferCandidates} matched transfers</button>}{learnedClassifications>0&&<button onClick={()=>bulkReconcile("learned-merchant-rule",learnedClassifications)} className="bg-emerald-700 text-white rounded-lg px-3 py-2 text-xs font-bold">Approve {learnedClassifications} learned matches</button>}</div><input value={approvalSearch} onChange={event=>{setApprovalSearch(event.target.value);setApprovalLimit(25);}} placeholder="Search date, merchant, amount, or AI category" className="border rounded-xl px-3 py-2 w-full text-sm bg-white"/><div className="flex justify-between mt-2 text-[11px] text-stone-500"><span>Showing {Math.min(approvalLimit,filteredPending.length)} of {filteredPending.length}</span>{approvalSearch && <button onClick={()=>setApprovalSearch("")} className="text-purple-700">Clear search</button>}</div></div><div className="max-h-[520px] overflow-y-auto divide-y">{filteredPending.slice(0,approvalLimit).map(x=><div key={x.id} className="p-3 flex flex-col sm:flex-row sm:items-center justify-between gap-3 text-sm hover:bg-stone-50"><div className="min-w-0"><div className="flex flex-wrap gap-x-2"><span className="text-stone-500 shrink-0">{x.date}</span><span className="font-medium break-words">{x.description}</span></div><div className="flex flex-wrap items-center gap-2 mt-1"><strong>{money.format(x.amount)}</strong>{x.suggestedCategory && <span className={`text-[10px] border rounded-full px-2 py-0.5 ${x.classificationSource==="cross-account-match"?"bg-blue-50 text-blue-700 border-blue-100":x.classificationSource==="learned-merchant-rule"?"bg-emerald-50 text-emerald-700 border-emerald-100":"bg-purple-50 text-purple-700 border-purple-100"}`}>{x.suggestedCategory} · {Math.round(Number(x.aiConfidence || 0)*100)}%</span>}{x.classificationSource&&<span className="text-[9px] uppercase text-stone-400">{x.classificationSource.replaceAll("-"," ")}</span>}</div></div><button onClick={()=>reconcile(x)} className="border rounded-lg px-3 py-2 text-xs shrink-0 hover:bg-white">Review and add</button></div>)}{filteredPending.length===0&&<p className="p-6 text-sm text-stone-500 text-center">No matching transactions.</p>}</div>{filteredPending.length>approvalLimit&&<div className="p-3 border-t bg-stone-50 text-center"><button onClick={()=>setApprovalLimit(limit=>limit+25)} className="border bg-white rounded-lg px-4 py-2 text-xs font-bold">Show 25 more</button></div>}</div>}</section> : <div className="bg-white border rounded-xl p-5 text-sm text-emerald-700">All imported transactions have been reviewed.</div>)}
  </div>;
}
